        throw new IllegalArgumentException("Set sizes must be positive integers");
    }

    List<V> set1 = new ArrayList<>();
    List<V> set2 = new ArrayList<>();

    // Create and add vertices to set 1
    for (int i = 0; i < set1Size; i++) {
