    }

    // Create and add vertices to set 2
    for (int i = 0; i < set2Size; i++) {
        V vertex = target.addNewVertex("v2_" + i);
        set2.add(vertex);
    }

    // Add edges between all vertices in set 1 and set 2
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}

