protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertexPath = new ArrayList<>();
    if (tour == null || graph == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour and graph must be non-null and tour must not be empty.");
    }

    // Find a starting edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    vertexPath.add(startVertex);

    // Use a set to track visited edges
    Set<E> visitedEdges = new HashSet<>();
    visitedEdges.add(startEdge);

    V currentVertex = graph.getEdgeTarget(startEdge);
    while (visitedEdges.size() < tour.size()) {
        for (E edge : tour) {
            if (!visitedEdges.contains(edge)) {
                if (graph.getEdgeSource(edge) == currentVertex) {
                    currentVertex = graph.getEdgeTarget(edge);
                    vertexPath.add(currentVertex);
                    visitedEdges.add(edge);
                    break;
                } else if (graph.getEdgeTarget(edge) == currentVertex) {
                    currentVertex = graph.getEdgeSource(edge);
                    vertexPath.add(currentVertex);
                    visitedEdges.add(edge);
                    break;
                }
            }
        }
    }

    // Check if the path forms a cycle
    if (!vertexPath.get(0).equals(vertexPath.get(vertexPath.size() - 1))) {
        throw new IllegalArgumentException("The provided edges do not form a valid tour.");
    }

    return new org.jgrapht.graph.GraphWalk<>(graph, vertexPath.get(0), vertexPath.get(vertexPath.size() - 1), vertexPath, null, 0.0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    if (pathEdges.isEmpty()) {
        return new GraphPathImpl<>(graph, null, pathEdges, 0.0);
    }

    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (!visitedEdges.equals(tour)) {
        E nextEdge = null;
        for (E edge : pathEdges) {
            if (!visitedEdges.contains(edge) && 
                (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Provided edges do not form a valid tour");
        }

        visitedEdges.add(nextEdge);
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        currentVertex = source.equals(currentVertex) ? target : source;
        pathVertices.add(currentVertex);
    }

    double weight = 0.0;
    for (E edge : pathEdges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    List<V> pathVertices = new ArrayList<>();
    Map<V, Integer> vertexDegree = new HashMap<>();

    // Calculate the degree of each vertex in the tour
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexDegree.put(source, vertexDegree.getOrDefault(source, 0) + 1);
        vertexDegree.put(target, vertexDegree.getOrDefault(target, 0) + 1);
    }

    // Find a starting vertex with an odd degree or any vertex otherwise
    V startVertex = null;
    for (Map.Entry<V, Integer> entry : vertexDegree.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }
    if (startVertex == null) {
        startVertex = graph.getEdgeSource(pathEdges.get(0));
    }

    // Reconstruct the path
    Deque<E> stack = new ArrayDeque<>();
    stack.push(pathEdges.get(0));
    while (!stack.isEmpty()) {
        E currentEdge = stack.peek();
        V currentVertex = graph.getEdgeTarget(currentEdge);
        if (tour.contains(currentEdge)) {
            pathVertices.add(currentVertex);
            tour.remove(currentEdge);
            stack.pop();
            for (E outgoingEdge : graph.outgoingEdgesOf(currentVertex)) {
                if (tour.contains(outgoingEdge)) {
                    stack.push(outgoingEdge);
                }
            }
        } else {
            stack.pop();
        }
    }

    // Ensure the path forms a cycle
    if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        throw new IllegalArgumentException("The edges do not form a valid tour");
    }

    return new GraphPathImpl<>(graph, startVertex, pathVertices, pathVertices.size() - 1);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0);
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    V currentVertex = null;
    Map<V, List<E>> adjacencyMap = new HashMap<>();

    // Build adjacency map
    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyMap.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacencyMap.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex with an odd degree (if exists)
    for (V vertex : adjacencyMap.keySet()) {
        if (adjacencyMap.get(vertex).size() % 2 != 0) {
            startVertex = vertex;
            break;
        }
    }

    // If no vertex with an odd degree, pick any vertex
    if (startVertex == null) {
        startVertex = adjacencyMap.keySet().iterator().next();
    }

    currentVertex = startVertex;
    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);

    // Hierholzer's algorithm to find Eulerian path/circuit
    while (!adjacencyMap.isEmpty() || !edges.isEmpty()) {
        if (!adjacencyMap.containsKey(currentVertex) || adjacencyMap.get(currentVertex).isEmpty()) {
            throw new IllegalArgumentException("The provided tour does not form a valid Eulerian path/circuit in the graph");
        }
        List<E> currentEdges = adjacencyMap.get(currentVertex);
        E newEdge = currentEdges.remove(0);
        edges.remove(newEdge);

        if (currentEdges.isEmpty()) {
            adjacencyMap.remove(currentVertex);
        }

        pathEdges.add(newEdge);
        currentVertex = graph.getEdgeTarget(newEdge).equals(currentVertex) ? graph.getEdgeSource(newEdge) : graph.getEdgeTarget(newEdge);
        pathVertices.add(currentVertex);
    }

    double weight = pathEdges.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, pathVertices, pathEdges, weight);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<V> pathVertices = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    // Start from an arbitrary vertex in the graph
    V startVertex = graph.vertexSet().iterator().next();
    pathVertices.add(startVertex);

    // Traverse the tour edges
    V currentVertex = startVertex;
    while (visitedEdges.size() < tour.size()) {
        if (!graph.containsVertex(currentVertex)) {
            throw new IllegalArgumentException("Tour contains edges not in the graph");
        }

        E nextEdge = null;
        for (E edge : tour) {
            if (!visitedEdges.contains(edge) && 
                (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Tour is not a valid path in the graph");
        }

        visitedEdges.add(nextEdge);

        V nextVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        pathVertices.add(nextVertex);
        currentVertex = nextVertex;
    }

    // Check if the path forms a cycle
    if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        throw new IllegalArgumentException("Tour does not form a cycle");
    }

