    }

    // Normalize the input path to end with a slash
    if (!path.endsWith("/")) {
        path += "/";
    }

    // Tokenize the paths
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    // Use a stack to manage the path
    LinkedList<String> pathStack = new LinkedList<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            pathStack.push(part);
        }
    }

    // Process the relative path
    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop(); // Move up one directory
            }
        } else if (!part.equals(".")) {
            pathStack.push(part); // Add the directory to the path
        }
    }

    // Build the result path
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        result.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    // Ensure the result has a leading slash if the original path had one
